const $=s=>document.querySelector(s);
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',accounts:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 10h18M7 16h4M7 6V3h10v3"/>',transactions:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',investments:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>',debts:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h3"/>',budgets:'<path d="M12 3v9h9A9 9 0 1 1 12 3Z"/><path d="M16 3a8 8 0 0 1 5 5h-5Z"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',cash:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M6 12h.01M18 12h.01"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.cash}</svg>`;
const pages={overview:['Overview','Financial overview','A clearer picture of where you are. A better plan for what’s next.'],accounts:['Accounts','All your accounts','Every balance, together. Keep your financial picture up to date.'],transactions:['Transactions','Money in. Money out.','The everyday details behind your bigger financial picture.'],savings:['Savings','Your savings, together','Add your savings accounts and keep their balances up to date.'],investments:['Investments','Build your tomorrow','Track the current value of your investment accounts.'],creditcards:['Credit cards','Your credit cards, together','See your limits, balances owed, and available credit in one place.'],debts:['Debts','A little closer to debt-free','Keep your balances, interest rates, and payments in view.'],budgets:['Budgets','Spend with intention','Give your monthly spending a little direction.'],categories:['Categories','Your categories, your way','Organize your income and expenses around the way you live.'],reports:['Reports','Where your money goes','See which categories take the biggest share of your spending.'],settings:['Settings','Make yourself at home','Manage your preferences and your financial data.']};
const defaultCategoryNames=['Salary','Freelance','Investment income','Other income','Housing','Groceries','Dining','Shopping','Transport','Entertainment','Utilities','Health','Other'];
icons.categories='<path d="m3 3 8 0 10 10-8 8L3 11Z"/><circle cx="7" cy="7" r="1"/>';
icons.savings=categoryIconChoices.savings.path;icons.creditcards=icons.debts;
icons.reports='<path d="M4 3v18h17M8 16v-4m5 4V7m5 9v-6"/>';
const colors=['#4572e9','#8caaf0','#a6d2c4','#e1c69b'];
const today=()=>new Date().toLocaleDateString('en-CA');
const uid=()=>crypto.randomUUID();
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,storageOK=true,page='overview',period=6,search='',typeFilter='all';
function sample(){const d=new Date(),year=d.getFullYear(),month=d.getMonth();const accounts=[{id:'a1',name:'Everyday chequing',institution:'TD Bank',type:'bank',balance:12480},{id:'a2',name:'High-interest savings',institution:'EQ Bank',type:'savings',balance:24500},{id:'a3',name:'Investment portfolio',institution:'Wealthsimple',type:'investment',balance:48320},{id:'a4',name:'Cash on hand',institution:'Personal',type:'cash',balance:450},{id:'a5',name:'Visa credit card',institution:'TD Bank',type:'debt',balance:2450,apr:19.99,payment:150},{id:'a6',name:'Student loan',institution:'Student loans',type:'debt',balance:12800,apr:4.5,payment:280}];const transactions=[];for(let i=5;i>=0;i--){const dt=(day)=>new Date(year,month-i,day).toLocaleDateString('en-CA');const entries=[['Paycheque','Salary',6400,'income',2],['Side project','Freelance',i%2?550:850,'income',5],['Monthly rent','Housing',1850,'expense',3],['Fresh market','Groceries',380+i*12,'expense',5],['Weekly groceries','Groceries',125,'expense',8],['Internet & phone','Utilities',145,'expense',9],['City transit','Transport',156,'expense',10],['Coffee & lunch','Dining',86+i*7,'expense',11],['Weekend dinner','Dining',94,'expense',12],['Home essentials','Shopping',245+i*15,'expense',13]];for(const [name,category,amount,type,day]of entries){const date=dt(day);if(date<=today())transactions.push({id:uid(),name,category,amount,type,date,accountId:'a1'});}}return{version:1,currency:'CAD',demo:true,accounts,transactions,budgets:[{id:uid(),category:'Housing',limit:2000},{id:uid(),category:'Groceries',limit:650},{id:uid(),category:'Dining',limit:300},{id:uid(),category:'Shopping',limit:400},{id:uid(),category:'Transport',limit:200},{id:uid(),category:'Utilities',limit:200}]};}
try{const raw=localStorage.getItem('folio-finance-v1');state=raw?validate(JSON.parse(raw)):sample();}catch{state=sample();}
function validate(d){if(!d||![1,2].includes(d.version)||!supportedCurrency(d.currency)||typeof d.demo!=='boolean'||!Array.isArray(d.accounts)||!Array.isArray(d.transactions)||!Array.isArray(d.budgets))throw Error('Invalid backup');validateCategories(d);normalizeCurrencies(d);const types=['bank','savings','cash','investment','debt'];const ids=new Set();for(const a of d.accounts){if(!a.id||ids.has(a.id)||typeof a.name!=='string'||typeof a.institution!=='string'||!supportedCurrency(a.currency)||!types.includes(a.type)||!Number.isFinite(a.balance)||a.balance<0||(['apr','payment'].some(k=>a[k]!=null&&(!Number.isFinite(a[k])||a[k]<0))))throw Error('Invalid account');if(a.debtKind!=null&&(a.debtKind!=='credit-card'||a.type!=='debt'||!Number.isFinite(a.creditLimit)||a.creditLimit<=0||a.creditLimit>999999999999))throw Error('Invalid credit card');ids.add(a.id);}for(const t of d.transactions){if(typeof t.name!=='string'||!supportedCurrency(t.currency)||t.currency!==d.accounts.find(a=>a.id===t.accountId)?.currency||!categoryNames(undefined,d).includes(t.category)||!['income','expense'].includes(t.type)||!Number.isFinite(t.amount)||t.amount<=0||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||!ids.has(t.accountId))throw Error('Invalid transaction');}for(const b of d.budgets)if(!supportedCurrency(b.currency)||!categoryNames(undefined,d).includes(b.category)||!Number.isFinite(b.limit)||b.limit<=0)throw Error('Invalid budget');if(d.transfers!=null&&(!Array.isArray(d.transfers)||d.transfers.some(t=>typeof t.from!=='string'||typeof t.to!=='string'||typeof t.date!=='string'||!supportedCurrency(t.currency)||!supportedCurrency(t.toCurrency)||!Number.isFinite(t.toAmount)||t.toAmount<=0||!Number.isFinite(t.amount)||t.amount<=0)))throw Error('Invalid transfer');return d;}
function save(){getCategories();normalizeCurrencies(state);try{localStorage.setItem('folio-finance-v1',JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Storage is unavailable. Export a backup to keep your changes.');}render();window.folioDatabase?.save(state);}
function money(n,compact=false){if(!Number.isFinite(n))return '—';return new Intl.NumberFormat('en-CA',{style:'currency',currency:state.currency,currencyDisplay:'code',maximumFractionDigits:compact?0:2,minimumFractionDigits:compact?0:2}).format(n);}
function total(type){return state.accounts.filter(a=>type==='assets'?a.type!=='debt':a.type===type).reduce((s,a)=>s+convertMoney(a.balance,currencyOf(a)),0);}
function totals(month){const ts=state.transactions.filter(t=>t.date.startsWith(month));const income=ts.filter(t=>t.type==='income').reduce((s,t)=>s+transactionValue(t),0),expense=ts.filter(t=>t.type==='expense').reduce((s,t)=>s+transactionValue(t),0);return{income,expense,net:income-expense};}
function monthKey(offset=0){const d=new Date();d.setMonth(d.getMonth()+offset,1);return d.toLocaleDateString('en-CA').slice(0,7);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function card(label,value,foot,ic,featured=false){return `<div class="stat stat-${ic} ${featured?'featured':''}"><div class="stat-label">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${money(value,true)}</div><div class="stat-foot">${foot}</div></div>`;}
function stats(){const m=totals(monthKey());return `<div class="stats">${card('Total net worth',total('assets')-total('debt'),'Your assets minus your debts','overview',true)}${card('Cash & bank balances',total('bank')+total('savings')+total('cash'),'Across your everyday accounts','accounts')}${card('Total investments',total('investment'),`${state.accounts.filter(a=>a.type==='investment').length} investment account${state.accounts.filter(a=>a.type==='investment').length===1?'':'s'} · Current value`,'investments')}${card('Total debt',total('debt'),`<span class="${m.net>=0?'positive':'negative'}">${money(m.net,true)} net cash flow</span> this month`,'debts')}</div>`;}
function panelHead(title,sub,action=''){return `<div class="panel-head"><div><h2>${title}</h2>${sub?`<p class="panel-sub">${sub}</p>`:''}</div>${action}</div>`;}
function cashFlowPeriods(selected=period,anchor=today()){
  if(selected!==1)return Array.from({length:selected},(_,i)=>monthKey(i-selected+1));
  return Array.from({length:7},(_,i)=>{const date=new Date(anchor+'T12:00:00');date.setDate(date.getDate()+i-6);return date.toLocaleDateString('en-CA');});
}
function chartPanel(){
  if(fxMissingCurrencies().length)return fxMissingPanel();
  const weekly=period===1,keys=cashFlowPeriods(),data=keys.map(totals);
  const sum=data.reduce((s,d)=>({income:s.income+d.income,expense:s.expense+d.expense}),{income:0,expense:0});
  const max=Math.max(...data.map(d=>Math.max(d.income,d.expense)),weekly?1:1000);
  const magnitude=10**Math.floor(Math.log10(max/4)),step=[1,2,5,10].find(n=>n>=max/4/magnitude)*magnitude;
  const top=weekly?step*4:Math.ceil(max/2000)*2000;
  let grid='',bars='';
  for(let i=0;i<=4;i++){
    const y=180-i*39,value=top*i/4,label=value>=1000?`${value/1000}k`:String(Number(value.toFixed(2)));
    grid+=`<line x1="47" x2="615" y1="${y}" y2="${y}" stroke="#edf1f7" stroke-dasharray="3 4"/><text x="0" y="${y+3}">${label}</text>`;
  }
  const slot=550/keys.length,w=Math.min(23,slot*.27);
  data.forEach((d,i)=>{
    const x=55+i*slot+slot/2,date=new Date(keys[i]+(weekly?'T12:00:00':'-02T12:00:00'));
    const label=date.toLocaleDateString('en-CA',weekly?{weekday:'short',day:'numeric'}:{month:'short'});
    bars+=`<rect x="${x-w-2}" y="${180-d.income/top*156}" width="${w}" height="${d.income/top*156}" rx="4" fill="#4775ee"><title>${keys[i]} income: ${money(d.income)}</title></rect><rect x="${x+2}" y="${180-d.expense/top*156}" width="${w}" height="${d.expense/top*156}" rx="4" fill="#b7c9ee"><title>${keys[i]} expenses: ${money(d.expense)}</title></rect><text text-anchor="middle" x="${x}" y="207">${label}</text>`;
  });
  return `<section class="panel">${panelHead('Cash flow',weekly?'Daily income and expenses · Last 7 days':'A little perspective on your ins and outs',`<div class="segmented" aria-label="Chart period">${[1,3,6,12].map(n=>`<button data-period="${n}" class="${period===n?'active':''}" aria-pressed="${period===n}">${n===1?'1W':n+'M'}</button>`).join('')}</div>`)}<div class="chart-summary"><div><label>TOTAL INCOME</label><b>${money(sum.income,true)}</b></div><div><label>TOTAL EXPENSES</label><b>${money(sum.expense,true)}</b></div></div><div class="chart"><svg viewBox="0 0 630 218" role="img" aria-label="Income and expenses over the last ${weekly?'7 days':period+' months'}">${grid}${bars}</svg><div class="legend" style="justify-content:center"><span><i></i>Income</span><span><i class="expense"></i>Expenses</span></div></div></section>`;
}
function allocation(){if(fxMissingCurrencies().length)return fxMissingPanel();const vals=[total('bank')+total('savings'),total('investment'),total('cash')],sum=vals.reduce((a,b)=>a+b,0);const parts=['Bank & savings','Investments','Cash'];let start=0;const gradient=vals.map((v,i)=>{let end=start+(sum?v/sum*100:0),part=`${colors[i]} ${start}% ${end}%`;start=end;return part;}).join(',');const net=totals(monthKey());return `<section class="panel">${panelHead('Asset allocation','Where your money lives',`<button class="text-button" data-page="accounts">Details <span>↗</span></button>`)}<div class="donut-layout">${interactiveDonut(parts.map((name,i)=>({name,amount:vals[i],color:colors[i]})),sum,'TOTAL ASSETS','total assets')}<div class="allocation-legend">${parts.map((p,i)=>`<button class="allocation-row chart-legend-button" ${donutTipAttributes(p,vals[i],sum?vals[i]/sum*100:0,'total assets')}><span><i class="dot" style="background:${colors[i]}"></i>${p}</span><b>${sum?Math.round(vals[i]/sum*100):0}%</b></button>`).join('')}</div></div><div class="insight">${icon('spark')}<span><b>${net.income?`${Math.round(net.net/net.income*100)}% of income left this month.`:'Your financial picture starts here.'}</b><br>${net.income?'Income minus recorded expenses. Keep tracking to see the full picture.':'Add your accounts and transactions to bring your dashboard to life.'}</span></div></section>`;}
function accountRows(){let a=state.accounts.filter(a=>a.type!=='debt');return a.length?a.slice(0,4).map((a,i)=>`<div class="account-row"><span class="account-logo" style="background:${['#e7f4ec','#edf1fd','#f4ece4','#ebf3fb'][i%4]};color:${['#399468','#6d80ac','#a98360','#5887b8'][i%4]}">${escapeHtml(a.institution.slice(0,2).toUpperCase())}</span><div class="account-info"><strong>${escapeHtml(a.name)}</strong><small>${escapeHtml(a.institution)} · ${typeName(a.type)}</small></div><div class="account-amount">${nativeMoney(a.balance,currencyOf(a))}<small>${currencyOf(a)}</small></div></div>`).join(''):'<div class="empty">Add your first account to get started.</div>';}
function typeName(type){return {bank:'Chequing',savings:'Savings',cash:'Cash',investment:'Investment',debt:'Debt'}[type];}
function transactionsTable(limit){let ts=state.transactions.filter(t=>(!search||`${t.name} ${t.category} ${state.accounts.find(a=>a.id===t.accountId)?.name}`.toLowerCase().includes(search.toLowerCase()))&&(typeFilter==='all'||t.type===typeFilter)).sort((a,b)=>b.date.localeCompare(a.date));if(limit)ts=ts.slice(0,limit);if(!ts.length)return '<div class="empty"><h2>No transactions yet</h2><p>Add a transaction to start tracking your cash flow.</p></div>';return `<div class="table-wrap"><table><thead><tr><th>TRANSACTION</th><th>CATEGORY</th><th>DATE</th><th>AMOUNT</th>${!limit?'<th></th>':''}</tr></thead><tbody>${ts.map(t=>`<tr><td><div class="transaction-name"><span class="account-logo" style="background:${t.type==='income'?'#eaf5ee':'#f1f3f8'};color:${t.type==='income'?'#559b75':'#8a98af'}">${t.type==='income'?'↙':'↗'}</span>${escapeHtml(t.name)}</div></td><td><button class="pill category-tag" data-recategorize="${escapeHtml(t.id)}" aria-label="Change category for ${escapeHtml(t.name)}">${categoryIconMarkup(t.category)}${escapeHtml(t.category)}</button></td><td style="white-space:nowrap">${new Date(t.date+'T12:00:00').toLocaleDateString('en-CA',{month:'short',day:'numeric'})}</td><td class="amount ${t.type}">${t.type==='income'?'+':'−'}${nativeMoney(t.amount,t.currency||state.currency)}<small class="fx-native-label">${t.currency!==state.currency?'≈ '+money(transactionValue(t)):''}</small></td>${!limit?`<td><button class="text-button danger" data-delete-txn="${escapeHtml(t.id)}" aria-label="Delete ${escapeHtml(t.name)}">✕</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function originalOverview(){return `${stats()}<div class="grid-main">${chartPanel()}${allocation()}</div><div class="grid-lower"><section class="panel">${panelHead('My accounts',`${state.accounts.length} accounts · One clear view`,`<button class="text-button" data-page="accounts">View all <span>↗</span></button>`)}<div class="account-list">${accountRows()}</div><button class="panel-bottom text-button" style="width:100%" data-add-account="bank">＋ Add an account</button></section><section class="panel">${panelHead('Recent transactions','The latest movement in your money',`<button class="text-button" data-page="transactions">View all <span>↗</span></button>`)}${transactionsTable(5)}</section></div>`;}
function isCreditCard(a){return a?.type==='debt'&&a.debtKind==='credit-card';}
function creditCardTotals(){return state.accounts.filter(isCreditCard).reduce((s,a)=>{s.count++;s.limit+=convertMoney(a.creditLimit,currencyOf(a));s.owed+=convertMoney(a.balance,currencyOf(a));s.available+=convertMoney(Math.max(0,a.creditLimit-a.balance),currencyOf(a));return s;},{count:0,limit:0,owed:0,available:0});}
function creditCardDetails(a){const available=Math.max(0,a.creditLimit-a.balance);return `<div class="credit-card-details"><div><span>Available Credit</span><b>${nativeMoney(available,currencyOf(a))}</b></div><div><span>Card Limit</span><b>${nativeMoney(a.creditLimit,currencyOf(a))}</b></div>${a.balance>a.creditLimit?`<p class="negative">Over limit by ${nativeMoney(a.balance-a.creditLimit,currencyOf(a))}</p>`:''}<p>+ increases Current Balance. − reduces it.</p></div>`;}
function creditCardsPage(){const s=creditCardTotals();return `<div class="stats credit-card-summary">${card('Available Credit',s.available,'Remaining credit across your cards','accounts')}${card('Current Balance',s.owed,'Combined amount owed on your cards','debts')}${card('Card Limit',s.limit,s.count+' credit card'+(s.count===1?'':'s')+' · Full limit when paid off','creditcards',true)}</div><p class="credit-summary-note">Available Credit = Card Limit − Current Balance. Totals are shown in ${escapeHtml(state.currency)} using your dashboard rates. Credit limits are not assets.</p>${accountCards('credit-card')}`;}
function creditCardModal(id){
 const a=state.accounts.find(a=>a.id===id),linked=!!a&&state.transactions.some(t=>t.accountId===id);
 modal(a?'Update credit card':'Add a credit card',field('Card name','name','text',a?.name||'','required maxlength="70" placeholder="e.g. My Visa"')+field('Bank or provider','institution','text',a?.institution||'','required maxlength="50"')+select('Card currency','accountCurrency',currencyOptions(),a?.currency||state.currency)+field('Available Credit','availableCredit','number',a?Math.max(0,a.creditLimit-a.balance):'','readonly aria-describedby="credit-available-help"')+field('Current Balance','balance','number',a?.balance??'','required min="0" max="999999999999" step="0.01"')+field('Card Limit','creditLimit','number',a?.creditLimit??'','required min="0.01" max="999999999999" step="0.01"')+'<p id="credit-available-help">Available Credit is calculated automatically. Current Balance is the amount you owe. Card Limit is the full credit available when your balance is paid off.</p>',f=>{
  const balance=Number(f.get('balance')),limit=Number(f.get('creditLimit')),currency=linked?currencyOf(a):f.get('accountCurrency');
  if(!Number.isFinite(balance)||balance<0||balance>999999999999||Math.abs(balance*100-Math.round(balance*100))>0.0001)throw Error('Enter a valid Current Balance with up to two decimal places.');
  if(!Number.isFinite(limit)||limit<=0||limit>999999999999||Math.abs(limit*100-Math.round(limit*100))>0.0001)throw Error('Enter a Card Limit greater than zero, with up to two decimal places.');
  if(!supportedCurrency(currency))throw Error('Choose a supported card currency.');
  const item={id:id||uid(),name:(f.get('name')||'').trim(),institution:(f.get('institution')||'').trim(),type:'debt',debtKind:'credit-card',currency,balance,creditLimit:limit,apr:a?.apr||0,payment:a?.payment||0};
  if(!item.name||!item.institution)throw Error('Enter a card name and bank or provider.');
  if(a)Object.assign(a,item);else state.accounts.push(item);save();toast('Card saved');
 });
 $('#field-accountCurrency').disabled=linked;
 function updateAvailable(){const balance=Number($('#field-balance').value),limit=Number($('#field-creditLimit').value);$('#field-availableCredit').value=$('#field-creditLimit').value&&Number.isFinite(balance)&&Number.isFinite(limit)?Math.max(0,Math.round((limit-balance)*100)/100):'';}
 $('#field-balance').oninput=updateAvailable;$('#field-creditLimit').oninput=updateAvailable;
}


function accountCards(type){const list=state.accounts.filter(a=>type==='credit-card'?isCreditCard(a):!type||a.type===type);if(!list.length)return `<section class="panel empty"><h2>${type==='credit-card'?'All your cards, in one place':type==='debt'?'A fresh start':type==='investment'?'Room to grow':type==='savings'?'A home for your savings':'All your accounts, in one place'}</h2><p>Add ${type==='credit-card'?'a credit card':type==='debt'?'a debt':type==='investment'?'an investment account':type==='savings'?'a savings account':'an account'} to start tracking.</p><button class="primary" data-add-account="${type||'bank'}">＋ Add ${type==='credit-card'?'credit card':type==='debt'?'debt':type==='savings'?'savings account':'account'}</button></section>`;return `${state.accounts.length>1?'<div class="toolbar"><button class="secondary" id="transfer-button">⇄ Transfer or pay a debt</button><span style="font-size:10px;color:#8b9ab0">Move money without affecting your cash flow.</span></div>':''}<div class="cards">${list.map(a=>`<article class="detail-card"><div class="account-logo">${icon(a.type==='debt'?'debts':a.type==='investment'?'investments':a.type==='savings'?'savings':'accounts')}</div><h2>${escapeHtml(a.name)}</h2><p>${escapeHtml(a.institution)} · ${isCreditCard(a)?'Credit card':typeName(a.type)}</p>${isCreditCard(a)?'<p class="credit-balance-label">Current Balance</p>':''}<div class="balance">${nativeMoney(a.balance,currencyOf(a))}</div>${currencyOf(a)!==state.currency?`<p class="fx-equivalent">≈ ${money(convertMoney(a.balance,currencyOf(a)))} in dashboard currency</p>`:''}<div class="budget-numbers"><span>${isCreditCard(a)?'':a.type==='debt'?`${a.apr||0}% interest`:'Current balance'}</span><span>${isCreditCard(a)?currencyOf(a):a.type==='debt'?`${nativeMoney(a.payment||0,currencyOf(a))}/mo`:currencyOf(a)}</span></div>${isCreditCard(a)?creditCardDetails(a):''}<div class="account-adjustments"><button class="account-add" data-account-add="${escapeHtml(a.id)}" aria-label="Add to ${escapeHtml(a.name)}">+</button><button class="account-subtract" data-account-subtract="${escapeHtml(a.id)}" aria-label="Subtract from ${escapeHtml(a.name)}">−</button></div><div class="detail-actions"><button class="text-button" data-edit-account="${escapeHtml(a.id)}">Update balance & details ↗</button><button class="text-button danger" data-delete-account="${escapeHtml(a.id)}">Remove</button></div></article>`).join('')}</div>${!type&&state.transfers?.length?`<section class="panel" style="margin-top:22px">${panelHead('Recent transfers','Transfers are excluded from income and expenses')}<div class="account-list">${state.transfers.slice(-5).reverse().map(t=>`<div class="account-row"><div class="account-info"><strong>${escapeHtml(t.from)} → ${escapeHtml(t.to)}</strong><small>${escapeHtml(t.date)}</small></div><b>${nativeMoney(t.amount,t.currency||state.currency)}${t.toCurrency&&t.toCurrency!==t.currency?`<small class="fx-native-label">→ ${nativeMoney(t.toAmount,t.toCurrency)}</small>`:''}</b></div>`).join('')}</div></section>`:''}`;}
function budgets(){if(fxMissingCurrencies().length)return fxMissingPanel();return `<p style="font-size:11px;margin-bottom:20px">${new Date().toLocaleDateString('en-CA',{month:'long',year:'numeric'})} · Spending is calculated from this month’s recorded expenses.</p><div class="cards">${state.budgets.map(b=>{const limit=convertMoney(b.limit,currencyOf(b)),spent=state.transactions.filter(t=>t.type==='expense'&&t.category===b.category&&t.date.startsWith(monthKey())).reduce((s,t)=>s+transactionValue(t),0);return `<article class="detail-card"><h2 class="category-with-icon">${categoryIconMarkup(b.category)}${escapeHtml(b.category)}</h2><div class="balance">${money(spent,true)} <span style="font-size:12px;color:#9ba7b9;font-weight:400">/ ${money(limit,true)}</span></div><div class="progress"><div style="width:${Math.min(100,spent/limit*100)}%;background:${spent>limit?'#d78a8a':'#5980e9'}"></div></div><div class="budget-numbers"><span>${Math.round(spent/limit*100)}% used</span><span>${money(Math.abs(limit-spent),true)} ${spent>limit?'over budget':'remaining'}</span></div><div class="detail-actions"><button class="text-button" data-edit-budget="${escapeHtml(b.id)}">Edit budget ↗</button><button class="text-button danger" data-delete-budget="${escapeHtml(b.id)}">Remove</button></div></article>`;}).join('')||'<section class="panel empty">Set your first monthly budget with the button above.</section>'}</div>`;}
function settings(){return `<section class="panel settings-panel"><h2>Your preferences</h2><div class="settings-row"><div><b>Currency</b><p>Choose the currency for unified totals. Account balances keep their own currency and are converted using the latest available reference rates.</p></div><select id="currency" aria-label="Currency">${currencyOptions().map(([c,label])=>`<option value="${c}" ${state.currency===c?'selected':''}>${label}</option>`).join('')}</select></div><div class="settings-row"><div><b>Export a backup</b><p>Download your accounts, transactions, and budgets. Keep a copy somewhere safe.</p></div><button class="secondary" id="export-backup">Export data ↓</button></div><div class="settings-row"><div><b>Restore a backup</b><p>Replace your saved database records with a Folio backup.</p></div><button class="secondary" id="import-backup">Import data ↑</button></div><div class="settings-row"><div><b>Your data is saved in SQLite</b><p>Records are saved to your private database and loaded when you sign in on another device. This browser keeps a recovery copy. Export backups whenever you need a portable copy.</p></div>${icon('shield')}</div><div class="settings-row"><div><b>Start fresh</b><p>Clear the accounts, transactions, and budgets in your saved workspace across devices.</p></div><button class="secondary danger" id="reset-data">Clear data</button></div></section>`;}
function render(){normalizeCurrencies(state);$('#fx-banner').innerHTML=fxBanner();hideChartTip(true);const p=pages[page];$('#nav').innerHTML=Object.entries(pages).map(([key,v])=>`<a href="#${key}" aria-label="${v[0]}" title="${v[0]}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(key)}<span>${v[0]}</span></a>`).join('');$('#crumb').textContent=p[0];$('#title').textContent=p[1];$('#subtitle').textContent=p[2];$('#currency-label').textContent=state.currency;$('#shield').innerHTML=icon('shield');$('.local-status').innerHTML=`<i style="background:${storageOK?'#47a88b':'#d78a8a'}"></i> ${storageOK?'Saved on this device':'Changes not saved'}`;$('#add-button').classList.toggle('hidden',page==='settings'||page==='reports');$('#add-button').textContent=({accounts:'＋ Add account',savings:'＋ Add savings account',investments:'＋ Add investment',creditcards:'＋ Add card',debts:'＋ Add debt',budgets:'＋ Create budget',categories:'＋ Add category'})[page]||'＋ Add transaction';$('#content').innerHTML=page==='overview'?overview():page==='accounts'?accountCards():page==='savings'?savingsPage():page==='investments'?`${cardStripInvestment()}${accountCards('investment')}`:page==='creditcards'?creditCardsPage():page==='debts'?`${cardStripDebt()}${accountCards('debt')}`:page==='transactions'?`<div class="toolbar"><input id="search" type="search" placeholder="Search transactions…" aria-label="Search transactions" value="${escapeHtml(search)}"><select id="type-filter" aria-label="Filter transaction type">${['all','income','expense'].map(t=>`<option value="${t}" ${t===typeFilter?'selected':''}>${t==='all'?'All transactions':t==='income'?'Income':'Expenses'}</option>`).join('')}</select><button class="secondary" data-page="categories">Manage categories</button><button class="secondary" id="export-csv">Export CSV ↓</button></div><section class="panel" id="transaction-results">${transactionsTable()}</section>`:page==='budgets'?budgets():page==='categories'?categoriesPage():page==='reports'?reportsPage():settings();}
function savingsPage(){
  const accounts=state.accounts.filter(a=>a.type==='savings'),count=accounts.length;
  return '<div class="savings-summary">'+card('Total savings',total('savings'),'Included in your assets and net worth','savings',true)+'<article class="stat"><div class="stat-label">Savings accounts<span class="stat-icon">'+icon('accounts')+'</span></div><div class="stat-value">'+count+'</div><div class="stat-foot">'+(count===1?'One account, ready to track':'All your savings balances in one place')+'</div></article></div><div class="savings-note">'+icon('savings')+'<span>Enter the amount currently in each account. To move money into savings from another tracked account, use <b>Transfer or pay a debt</b>.</span></div>'+accountCards('savings');
}
function cardStripInvestment(){return `<div class="stats" style="grid-template-columns:repeat(2,1fr)">${card('Investment value',total('investment'),'Update balances as your portfolio changes','investments',true)}${card('Total assets',total('assets'),'Bank balances, cash, and investments','accounts')}</div>`;}
function cardStripDebt(){return `<div class="stats" style="grid-template-columns:repeat(2,1fr)">${card('Outstanding debt',total('debt'),'Combined balance of your debt accounts','debts',true)}${card('Monthly payments',state.accounts.filter(a=>a.type==='debt').reduce((s,a)=>s+convertMoney(a.payment||0,currencyOf(a)),0),'Sum of the monthly payments you entered','cash')}</div>`;}
function modal(title,body,onSave){$('#modal-form button[type="submit"]').textContent='Save changes';$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSave(new FormData(e.target));$('#modal').close();}catch(err){toast(err.message);}};$('#modal').showModal();}
function field(label,name,type,value='',extra=''){return `<label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${escapeHtml(value)}" ${extra}>`;}
function select(label,name,options,value){return `<label for="field-${name}">${label}</label><select id="field-${name}" name="${name}">${options.map(([v,l])=>`<option value="${escapeHtml(v)}" ${value===v?'selected':''}>${escapeHtml(l)}</option>`).join('')}</select>`;}
function accountModal(type='bank',id){
  const a=state.accounts.find(a=>a.id===id),linked=!!a&&state.transactions.some(t=>t.accountId===id);
  const credit=isCreditCard(a)||type==='credit-card';if(credit){creditCardModal(id);return;}
  modal(credit?(a?'Update credit card':'Add a credit card'):(a?'Update account':'Add an account'),field(credit?'Card name':'Account name','name','text',a?.name||'','required maxlength="70" placeholder="e.g. My savings"')+field('Bank or provider','institution','text',a?.institution||'','required maxlength="50" placeholder="e.g. GTBank, TD, Wise"')+select('Account type','type',Object.entries({bank:'Bank / chequing',savings:'Savings',cash:'Cash',investment:'Investment',debt:'Debt / loan','credit-card':'Credit card'}),(isCreditCard(a)?'credit-card':a?.type)||type)+select('Account currency','accountCurrency',currencyOptions(),a?.currency||state.currency)+field(credit?'Amount owed in this card’s currency':'Current balance in this account’s currency','balance','number',a?.balance??'','required min="0" max="999999999999" step="0.01"')+`<div id="debt-fields" ${!['debt','credit-card'].includes(a?.type||type)?'hidden':''}>`+field('Annual interest rate (%)','apr','number',a?.apr||0,'min="0" max="100" step="0.01"')+field('Monthly payment in this account’s currency','payment','number',a?.payment||0,'min="0" step="0.01"')+`</div><div id="credit-limit-fields" ${(isCreditCard(a)||type==='credit-card')?'':'hidden'}>`+field('Card limit in this account’s currency','creditLimit','number',a?.creditLimit??'','min="0.01" max="999999999999" step="0.01"')+`</div><p>${linked?'Currency is locked while this account has transactions. ':''}Enter the actual balance in the selected currency. Dashboard totals convert automatically; changing an empty account’s currency re-labels its balance without exchanging money.</p>`,f=>{
    const kind=f.get('type'),type=kind==='credit-card'?'debt':kind,currency=linked?currencyOf(a):f.get('accountCurrency')||a?.currency||state.currency;
    if(!supportedCurrency(currency))throw Error('Choose a supported account currency.');
    if(a&&a.type!==type&&linked)throw Error('Remove linked transactions before changing account type.');
    const item={id:id||uid(),name:f.get('name').trim(),institution:f.get('institution').trim(),type,currency,balance:Number(f.get('balance')),apr:Number(f.get('apr')||0),payment:Number(f.get('payment')||0)};
    if(kind==='credit-card'){const limit=Number(f.get('creditLimit'));if(!Number.isFinite(limit)||limit<=0||limit>999999999999||Math.abs(limit*100-Math.round(limit*100))>0.0001)throw Error('Enter a card limit greater than zero, with up to two decimal places.');item.debtKind='credit-card';item.creditLimit=limit;}if(!item.name||!item.institution)throw Error('Please enter an account name and provider.');if(a&&kind!=='credit-card'){delete a.debtKind;delete a.creditLimit;}if(a)Object.assign(a,item);else state.accounts.push(item);save();toast('Account saved');
  });$('#field-accountCurrency').disabled=linked;$('#field-creditLimit').disabled=!credit;$('#field-creditLimit').required=credit;$('#field-type').onchange=e=>{$('#debt-fields').hidden=e.target.value!=='debt';$('#credit-limit-fields').hidden=e.target.value!=='credit-card';$('#field-creditLimit').disabled=e.target.value!=='credit-card';$('#field-creditLimit').required=e.target.value==='credit-card';};
}
function txnModal(accountId,direction){
  if(!state.accounts.length){toast('Add an account first to record a transaction.');accountModal();return;}
  const selected=state.accounts.find(a=>a.id===accountId)||state.accounts[0],quick=direction===1||direction===-1;
  const selectedType=quick?((direction===1)!==(selected.type==='debt')?'income':'expense'):'expense';
  const title=quick?(selected.type==='debt'?(direction===1?'Increase debt':'Reduce debt'):(direction===1?'Add money':'Subtract money')):'Add a transaction';
  modal(title,field('Description','name','text','','required maxlength="90" placeholder="e.g. Salary, groceries, or payment"')+select('Type','type',[['expense','Expense'],['income','Income']],selectedType)+select('Account','accountId',state.accounts.map(a=>[a.id,`${a.name} · ${currencyOf(a)}`]),selected.id)+field('Amount in '+currencyOf(selected),'amount','number','','required min="0.01" max="999999999" step="0.01"')+select('Category','category',categoryNames(selectedType).map(c=>[c,c]),categoryNames(selectedType)[0])+field('Date','date','date',today(),'required')+`<p>${quick?'This will '+(direction===1?'increase':'decrease')+' the selected '+(selected.type==='debt'?'debt':'account')+' balance and create a transaction. ':''}Use the account’s native currency. For money moved between accounts or debt payments from another account, use Transfer or pay a debt.</p>`,f=>{
    const a=state.accounts.find(a=>a.id===(quick?selected.id:f.get('accountId')));if(!a)throw Error('Choose an account.');
    const t={id:uid(),name:f.get('name').trim(),type:quick?selectedType:f.get('type'),amount:Number(f.get('amount')),accountId:a.id,currency:currencyOf(a),category:f.get('category'),date:f.get('date')};
    if(quick&&a.id!==selected.id)throw Error('Use the selected account.');
    if(!Number.isFinite(t.amount)||t.amount<=0||t.amount>999999999||Math.abs(t.amount*100-Math.round(t.amount*100))>0.0001)throw Error('Enter a positive amount with up to two decimal places.');
    if(!t.name)throw Error('Please enter a description.');if(t.date>today())throw Error('Record transactions on or before today.');if(!categoryNames(t.type).includes(t.category))throw Error('Choose a category for this transaction type.');
    const delta=t.amount*(t.type==='income'?1:-1)*(a.type==='debt'?-1:1);if(a.balance+delta<0)throw Error(a.type==='debt'?'This would reduce debt below zero.':'This account has insufficient funds. Check its balance.');a.balance=Math.round((a.balance+delta)*100)/100;state.transactions.push(t);save();toast('Transaction recorded');
  });
  $('#field-type').onchange=e=>{$('#field-category').innerHTML=categoryNames(e.target.value).map(c=>`<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');};
  $('#field-accountId').onchange=e=>{const a=state.accounts.find(a=>a.id===e.target.value);document.querySelector('label[for="field-amount"]').textContent='Amount in '+currencyOf(a);};
  if(quick){$('#field-accountId').disabled=true;$('#field-type').disabled=true;}
}
function budgetModal(id){const b=state.budgets.find(b=>b.id===id),currency=b?.currency||state.currency;modal(b?'Edit monthly budget':'Create a monthly budget',select('Spending category','category',categoryNames('expense').map(c=>[c,c]),b?.category||'Groceries')+field('Monthly limit in '+currency,'limit','number',b?.limit||'','required min="0.01" max="999999999" step="0.01"')+'<p>Budgets keep their original currency. Limits and spending are converted into your dashboard currency for comparison.</p>',f=>{const category=f.get('category');if(state.budgets.some(x=>x.category===category&&x.id!==id))throw Error('This category already has a budget.');const item={id:id||uid(),category,limit:Number(f.get('limit')),currency};if(b)Object.assign(b,item);else state.budgets.push(item);save();toast('Budget saved');});}
function confirmAction(title,message,action){modal(title,`<p>${escapeHtml(message)}</p>`,()=>{action();save();toast('Changes saved');});$('#modal-form button[type="submit"]').textContent='Confirm';}
function transferModal(){
  modal('Transfer or pay a debt',select('From account','from',state.accounts.map(a=>[a.id,`${a.name} · ${currencyOf(a)}`]),state.accounts[0].id)+select('To account','to',state.accounts.map(a=>[a.id,`${a.name} · ${currencyOf(a)}`]),state.accounts[1].id)+field('Amount sent','amount','number','','required min="0.01" max="999999999999" step="0.01"')+'<div id="received-fields">'+field('Amount received','received','number','','min="0.01" max="999999999999" step="0.01"')+'</div><div class="transfer-estimate" id="transfer-estimate"></div>'+field('Date','date','date',today(),'required')+'<p>For different currencies, enter the amount your bank actually credited. The estimate uses reference rates and does not include bank fees. Transfers are excluded from income and expenses.</p>',f=>{
    const from=state.accounts.find(a=>a.id===f.get('from')),to=state.accounts.find(a=>a.id===f.get('to')),amount=Number(f.get('amount')),cross=currencyOf(from)!==currencyOf(to),received=cross?Number(f.get('received')):amount;
    if(from===to)throw Error('Choose two different accounts.');if(!Number.isFinite(amount)||amount<=0||!Number.isFinite(received)||received<=0)throw Error('Enter the amount sent and the amount received.');if(f.get('date')>today())throw Error('Record transfers on or before today.');
    if((from.type!=='debt'&&from.balance<amount)||(to.type==='debt'&&to.balance<received))throw Error('Check the balance: this transfer would take an account below zero.');
    from.balance=Math.round((from.balance+(from.type==='debt'?amount:-amount))*100)/100;to.balance=Math.round((to.balance+(to.type==='debt'?-received:received))*100)/100;(state.transfers??=[]).push({from:from.name,to:to.name,date:f.get('date'),amount,currency:currencyOf(from),toAmount:received,toCurrency:currencyOf(to)});save();toast('Transfer recorded');
  });
  const update=()=>{const from=state.accounts.find(a=>a.id===$('#field-from').value)||state.accounts[0],to=state.accounts.find(a=>a.id===$('#field-to').value)||state.accounts[1],cross=currencyOf(from)!==currencyOf(to),sent=Number($('#field-amount').value),estimated=convertMoney(sent,currencyOf(from),currencyOf(to));$('#received-fields').hidden=!cross;$('#field-received').required=cross;document.querySelector('label[for="field-amount"]').textContent='Amount sent · '+currencyOf(from);document.querySelector('label[for="field-received"]').textContent='Amount received · '+currencyOf(to);$('#transfer-estimate').textContent=cross?(Number.isFinite(estimated)?'Reference estimate: '+nativeMoney(estimated,currencyOf(to))+'. Edit the received amount to match your bank.':'No rate is available. Enter the actual amount received.'): 'Both accounts use '+currencyOf(from)+'. The same amount is moved.';if(cross)$('#field-received').value=sent>0&&Number.isFinite(estimated)?estimated.toFixed(2):'';};
  $('#field-from').onchange=update;$('#field-to').onchange=update;$('#field-amount').oninput=update;update();
}

document.addEventListener('click',e=>{if(e.target.closest('#transfer-button'))transferModal();});
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.page){location.hash=d.page;return;}if(d.period){period=Number(d.period);render();return;}if(d.addAccount){accountModal(d.addAccount);return;}if(d.accountAdd){txnModal(d.accountAdd,1);return;}if(d.accountSubtract){txnModal(d.accountSubtract,-1);return;}if(d.editAccount){accountModal('bank',d.editAccount);return;}if(d.editBudget){budgetModal(d.editBudget);return;}if(d.deleteBudget){confirmAction('Remove budget?','This removes the monthly limit. Your transactions will stay.',()=>state.budgets=state.budgets.filter(b=>b.id!==d.deleteBudget));return;}if(d.deleteAccount){if(state.transactions.some(t=>t.accountId===d.deleteAccount)){toast('Remove this account’s transactions before removing the account.');return;}confirmAction('Remove account?','This account and its balance will be removed from your dashboard.',()=>state.accounts=state.accounts.filter(a=>a.id!==d.deleteAccount));return;}if(d.deleteTxn){confirmAction('Delete transaction?','This will remove the transaction and reverse its effect on the account balance.',()=>{const t=state.transactions.find(t=>t.id===d.deleteTxn),a=state.accounts.find(a=>a.id===t.accountId);const value=a.balance-t.amount*(t.type==='income'?1:-1)*(a.type==='debt'?-1:1);if(value<0)throw Error('Update this account’s balance before reversing this transaction.');a.balance=Math.round(value*100)/100;state.transactions=state.transactions.filter(t=>t.id!==d.deleteTxn);});return;}switch(el.id){case'add-button':page==='accounts'?accountModal():page==='savings'?accountModal('savings'):page==='investments'?accountModal('investment'):page==='creditcards'?accountModal('credit-card'):page==='debts'?accountModal('debt'):page==='budgets'?budgetModal():page==='categories'?categoryModal():txnModal();break;case'close-modal':case'cancel-modal':$('#modal').close();break;case'settings-button':location.hash='settings';break;case'reset-data':confirmAction('Start with a clean slate?', 'This clears all accounts, transactions, and budgets in your database across devices. Export a backup first if you want to keep them.',()=>state={version:1,currency:state.currency,demo:false,accounts:[],transactions:[],budgets:[]});break;case'export-backup':download(`folio-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Backup downloaded');break;case'import-backup':$('#import-file').click();break;case'export-csv':const rows=[['Date','Description','Type','Category','Account','Amount','Currency'],...state.transactions.map(t=>[t.date,t.name,t.type,t.category,state.accounts.find(a=>a.id===t.accountId)?.name,t.type==='expense'?-t.amount:t.amount,t.currency||state.currency])];download(`folio-transactions-${today()}.csv`,rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@\t\r]/,"'$&")+'"').join(',')).join('\r\n'),'text/csv');break;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#transaction-results').innerHTML=transactionsTable();}});
document.addEventListener('change',e=>{if(e.target.id==='type-filter'){typeFilter=e.target.value;$('#transaction-results').innerHTML=transactionsTable();}if(e.target.id==='currency'){normalizeCurrencies(state);state.currency=e.target.value;save();toast('Unified totals updated; native balances are unchanged.');}});
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5000000){toast('Please use a backup smaller than 5 MB.');return;}try{const data=validate(JSON.parse(await file.text()));confirmAction('Restore this backup?',`Replace your saved database records with ${data.accounts.length} accounts and ${data.transactions.length} transactions?`,()=>state=data);}catch{toast('That file is not a valid Folio backup.');}};
function navigate(){page=location.hash.slice(1);if(!pages[page])page='overview';search='';typeFilter='all';render();window.scrollTo(0,0);}
function getCategories(data=state){
  if(!data.categories)data.categories=defaultCategoryNames.map((name,i)=>({name,type:i<4?'income':'expense'}));
  if(Array.isArray(data.categories))for(const c of data.categories)if(c&&c.icon==null)c.icon=defaultCategoryIcon(c.name,c.type);
  return data.categories;
}
function categoryIconMarkup(name){const category=getCategories().find(c=>c.name===name);return categorySymbol(category?.icon||'other');}
function categoryNames(type,data=state){return getCategories(data).filter(c=>!type||c.type===type).map(c=>c.name);}
function validateCategories(data){
  const list=getCategories(data),seen=new Set();
  if(!Array.isArray(list)||!list.length)throw Error('Invalid categories');
  for(const c of list){if(!c||typeof c.name!=='string'||!c.name.trim()||c.name!==c.name.trim()||c.name.length>50||!['income','expense'].includes(c.type)||seen.has(c.name.toLowerCase())||!hasCategoryIcon(c.icon))throw Error('Invalid category');seen.add(c.name.toLowerCase());}
  if(!list.some(c=>c.type==='income')||!list.some(c=>c.type==='expense'))throw Error('Keep an income and expense category');
}
function updateCategory(oldName,name,type,iconKey){
  name=name.trim();if(!name||name.length>50)throw Error('Enter a category name of 1–50 characters.');
  if(!['income','expense'].includes(type))throw Error('Choose a category type.');
  const list=getCategories(),existing=list.find(c=>c.name===oldName);
  const chosenIcon=iconKey??existing?.icon??defaultCategoryIcon(name,type);
  if(!hasCategoryIcon(chosenIcon))throw Error('Choose an icon from the list.');
  if(list.some(c=>c!==existing&&c.name.toLowerCase()===name.toLowerCase()))throw Error('A category with this name already exists.');
  if(oldName&&!existing)throw Error('Category not found.');
  if(existing&&existing.type!==type){
    if(state.transactions.some(t=>t.category===oldName)||state.budgets.some(b=>b.category===oldName))throw Error('This category is in use. Keep its type or create a new category.');
    if(list.filter(c=>c.type===existing.type).length===1)throw Error('Keep at least one category of each type.');
  }
  if(existing){existing.name=name;existing.type=type;existing.icon=chosenIcon;for(const t of state.transactions)if(t.category===oldName)t.category=name;for(const b of state.budgets)if(b.category===oldName)b.category=name;}
  else list.push({name,type,icon:chosenIcon});
}
function categoryModal(name){const c=getCategories().find(c=>c.name===name);modal(c?'Edit category':'Add a category',field('Category name','name','text',c?.name||'','required maxlength="50" placeholder="e.g. Childcare"')+select('Category type','type',[['expense','Expense'],['income','Income']],c?.type||'expense')+categoryIconPicker(c?.icon||'other')+'<p>Renaming a category also updates its existing transactions and budgets.</p>',f=>{updateCategory(c?.name,f.get('name'),f.get('type'),f.get('icon')||undefined);save();toast('Category saved');});}
function categoriesPage(){return `<div class="category-intro"><span>${getCategories().length} categories</span><span>Rename a category at any time. Your history stays together.</span></div><div class="category-columns">${['expense','income'].map(type=>`<section class="panel">${panelHead(type==='expense'?'Expense categories':'Income categories',type==='expense'?'Give every outgoing dollar a home':'Keep track of your income sources')}<div class="category-list">${getCategories().filter(c=>c.type===type).map(c=>{const count=state.transactions.filter(t=>t.category===c.name).length;return `<div class="category-item"><span class="account-logo">${categorySymbol(c.icon)}</span><div class="account-info"><strong>${escapeHtml(c.name)}</strong><small>${count} transaction${count===1?'':'s'}${state.budgets.some(b=>b.category===c.name)?' · Budget set':''}</small></div><button class="secondary" data-edit-category="${escapeHtml(c.name)}" aria-label="Edit ${escapeHtml(c.name)} category">Edit</button></div>`;}).join('')}</div></section>`).join('')}</div>`;}
function recategorizeModal(id){const t=state.transactions.find(t=>t.id===id);if(!t)return;modal('Change transaction category',`<p>${escapeHtml(t.name)} · ${nativeMoney(t.amount,t.currency||state.currency)}</p>`+select('Category','category',categoryNames(t.type).map(c=>[c,c]),t.category),f=>{const name=f.get('category');if(!categoryNames(t.type).includes(name))throw Error('Choose a valid category.');t.category=name;save();toast('Transaction category updated');});}
let reportPreset='month',reportFrom=monthKey()+'-01',reportTo=today(),reportAccount='all';
const reportColors=['#4572e9','#80a0eb','#65ad99','#c5a164','#9a84c6','#6ba9c1','#d8918d','#8ca67b','#a2aec5'];
function spendingReport(from,to,account='all'){
  const expenses=state.transactions.filter(t=>t.type==='expense'&&t.date>=from&&t.date<=to&&(account==='all'||t.accountId===account));
  if(expenses.some(t=>!Number.isFinite(transactionValue(t))))return {rows:[],total:NaN,count:expenses.length,unavailable:true};
  const grouped=new Map();for(const t of expenses){const row=grouped.get(t.category)||{name:t.category,cents:0,count:0};row.cents+=Math.round(transactionValue(t)*100);row.count++;grouped.set(t.category,row);}
  const cents=expenses.reduce((sum,t)=>sum+Math.round(transactionValue(t)*100),0);
  const rows=[...grouped.values()].sort((a,b)=>b.cents-a.cents||a.name.localeCompare(b.name)).map((r,i)=>({...r,amount:r.cents/100,percent:cents?r.cents/cents*100:0,color:reportColors[i%reportColors.length]}));
  return{rows,total:cents/100,count:expenses.length};
}
function percent(n){return n.toFixed(1)+'%';}
function reportDatesLabel(){return `${escapeHtml(reportFrom)} to ${escapeHtml(reportTo)}`;}
function reportBody(){if(fxMissingCurrencies().length)return fxMissingPanel();
  if(!reportFrom||!reportTo||reportFrom>reportTo)return '<section class="panel empty"><h2>Choose a valid date range</h2><p>The start date must be on or before the end date.</p></section>';
  const r=spendingReport(reportFrom,reportTo,reportAccount),top=r.rows[0];
  if(!top)return '<section class="panel empty"><h2>No expenses in this period</h2><p>Try another date range or account, or add an expense to see where your money goes.</p><button class="primary" data-page="transactions">Go to transactions ↗</button></section>';
  let cursor=0;const stops=r.rows.map(row=>{const start=cursor;cursor+=row.percent;return `${row.color} ${start}% ${cursor}%`;}).join(',');
  return `<div class="report-stats"><article class="stat featured"><div class="stat-label">Total expenses</div><div class="stat-value">${money(r.total)}</div><div class="stat-foot">${r.count} expense transactions</div></article><article class="stat"><div class="stat-label">Biggest spending category</div><div class="report-top-name">${categoryIconMarkup(top.name)}${escapeHtml(top.name)}</div><div class="stat-foot"><span class="positive">${percent(top.percent)}</span> of total expenses · ${money(top.amount)}</div></article><article class="stat"><div class="stat-label">Categories with spending</div><div class="stat-value">${r.rows.length}</div><div class="stat-foot">Ranked from highest to lowest</div></article></div><div class="report-layout"><section class="panel">${panelHead('Share of your spending','Category expenses ÷ total expenses × 100')}<div class="report-donut">${interactiveDonut(r.rows,r.total,'TOTAL SPENDING','total expenses')}</div><div class="report-legend">${r.rows.map(row=>`<button class="allocation-row chart-legend-button" ${donutTipAttributes(row.name,row.amount,row.percent,'total expenses')}><span><i class="dot" style="background:${row.color}"></i>${categoryIconMarkup(row.name)}${escapeHtml(row.name)}</span><b>${percent(row.percent)}</b></button>`).join('')}</div></section><section class="panel">${panelHead('Your biggest expenses','A clear breakdown, category by category')}<div class="spending-bars">${r.rows.map((row,i)=>`<div class="spending-row"><div class="spending-heading"><span><i class="dot" style="background:${row.color}"></i>${categoryIconMarkup(row.name)}${escapeHtml(row.name)}${i===0?'<small class="largest-badge">Largest share</small>':''}</span><b>${percent(row.percent)}</b></div><div class="progress"><div style="width:${row.percent}%;background:${row.color}"></div></div><div class="budget-numbers"><span>${row.count} transaction${row.count===1?'':'s'}</span><span>${money(row.amount)}</span></div></div>`).join('')}</div></section></div><section class="panel report-table">${panelHead('Spending detail',reportDatesLabel(),'<button class="secondary" id="export-report">Export report ↓</button>')}<div class="table-wrap"><table><thead><tr><th>CATEGORY</th><th>TRANSACTIONS</th><th>AMOUNT SPENT</th><th>SHARE OF EXPENSES</th></tr></thead><tbody>${r.rows.map(row=>`<tr><td>${categoryIconMarkup(row.name)}${escapeHtml(row.name)}</td><td>${row.count}</td><td>${money(row.amount)}</td><td><b>${percent(row.percent)}</b></td></tr>`).join('')}<tr class="report-total"><td>Total</td><td>${r.count}</td><td>${money(r.total)}</td><td>100.0%</td></tr></tbody></table></div></section><p class="report-note">Amounts converted into the dashboard currency using latest reference rates, not historical rates. Based on recorded expenses only. Income, account transfers, and debt payments recorded as transfers are excluded. Percentages are rounded to one decimal place.</p>`;
}
function reportsPage(){return `<section class="panel report-filters"><div>${select('Period','report-preset',[['month','This month'],['lastMonth','Last month'],['year','This year'],['all','All time'],['custom','Custom dates']],reportPreset)}</div><div>${field('From','report-from','date',reportFrom)}</div><div>${field('To','report-to','date',reportTo)}</div><div>${select('Account','report-account',[['all','All accounts'],...state.accounts.map(a=>[a.id,a.name])],reportAccount)}</div></section><div id="report-body">${reportBody()}</div>`;}
function overview(){const r=spendingReport(monthKey()+'-01',today()),top=r.rows[0];return originalOverview()+`<section class="panel overview-spending">${panelHead('Where your money goes','Your spending categories this month','<button class="text-button" data-page="reports">Full spending report ↗</button>')}${top?`<div class="overview-spending-content"><div><span class="eyebrow">BIGGEST SHARE</span><h2>${categoryIconMarkup(top.name)}${escapeHtml(top.name)} <span>${percent(top.percent)}</span></h2><p>${money(top.amount)} of ${money(r.total)} in expenses this month.</p></div><div class="overview-top-categories">${r.rows.slice(0,3).map(row=>`<div><span>${categoryIconMarkup(row.name)}${escapeHtml(row.name)}</span><b>${percent(row.percent)}</b><div class="progress"><div style="width:${row.percent}%;background:${row.color}"></div></div></div>`).join('')}</div></div>`:'<div class="empty">Add expenses to see which categories take the largest share.</div>'}</section>`;}
function setReportPreset(value){reportPreset=value;reportTo=today();if(value==='month')reportFrom=monthKey()+'-01';if(value==='lastMonth'){reportFrom=monthKey(-1)+'-01';reportTo=new Date(new Date().getFullYear(),new Date().getMonth(),0).toLocaleDateString('en-CA');}if(value==='year')reportFrom=today().slice(0,4)+'-01-01';if(value==='all'){const dates=state.transactions.map(t=>t.date).sort();reportFrom=dates[0]||monthKey()+'-01';reportTo=dates.at(-1)>today()?dates.at(-1):today();}}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.editCategory)categoryModal(el.dataset.editCategory);if(el.dataset.recategorize)recategorizeModal(el.dataset.recategorize);if(el.id==='export-report'){if(fxMissingCurrencies().length){toast('Load exchange rates before exporting a converted report.');return;}
  const r=spendingReport(reportFrom,reportTo,reportAccount),rows=[['Category','Transactions','Amount spent','Share of expenses (%)','Currency','From','To'],...r.rows.map(row=>[row.name,row.count,row.amount.toFixed(2),row.percent.toFixed(1),state.currency,reportFrom,reportTo])];
  download(`folio-spending-${reportFrom}-${reportTo}.csv`,rows.map(row=>row.map(value=>'"'+String(value).replace(/"/g,'""').replace(/^[=+@\t\r-]/,"'$&")+'"').join(',')).join('\r\n'),'text/csv');
}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='field-report-preset'){setReportPreset(e.target.value);render();}if(id==='field-report-from'||id==='field-report-to'){reportPreset='custom';if(id.endsWith('from'))reportFrom=e.target.value;else reportTo=e.target.value;$('#field-report-preset').value='custom';$('#report-body').innerHTML=reportBody();}if(id==='field-report-account'){reportAccount=e.target.value;$('#report-body').innerHTML=reportBody();}});

function donutTipAttributes(label,amount,share,denominator){return `data-chart-tip data-tip-label="${escapeHtml(label)}" data-tip-amount="${escapeHtml(money(amount))}" data-tip-share="${share.toFixed(1)}%" data-tip-denominator="${escapeHtml(denominator)}" aria-label="${escapeHtml(label)}: ${escapeHtml(money(amount))}, ${share.toFixed(1)}% of ${escapeHtml(denominator)}"`;}
function donutSegmentPath(start,share){
  const point=(radius,angle)=>{const radians=(angle-90)*Math.PI/180;return [100+radius*Math.cos(radians),100+radius*Math.sin(radians)];};
  if(share>=100)return 'M100 6 A94 94 0 1 1 100 194 A94 94 0 1 1 100 6 M100 32 A68 68 0 1 0 100 168 A68 68 0 1 0 100 32 Z';
  const a=point(94,start*3.6),b=point(94,(start+share)*3.6),c=point(68,(start+share)*3.6),d=point(68,start*3.6),large=share>50?1:0;
  return `M${a} A94 94 0 ${large} 1 ${b} L${c} A68 68 0 ${large} 0 ${d} Z`;
}
function interactiveDonut(rows,sum,label,denominator){let start=0;return `<div class="donut interactive-donut"><svg viewBox="0 0 200 200" role="group" aria-label="${escapeHtml(label)} by category"><circle cx="100" cy="100" r="81" fill="none" stroke="#edf1f7" stroke-width="26"/>${rows.filter(r=>r.amount>0).map(row=>{const share=sum?row.amount/sum*100:0,path=donutSegmentPath(start,share);start+=share;return `<path d="${path}" fill="${row.color}" fill-rule="evenodd" role="button" tabindex="0" ${donutTipAttributes(row.name,row.amount,share,denominator)}/>`;}).join('')}</svg><div class="donut-center">${escapeHtml(label)}<b>${money(sum,true)}</b></div></div>`;}
let pinnedChartTip=null,describedChartTarget=null;
function hideChartTip(clearPinned=false){if(pinnedChartTip&&!clearPinned)return;pinnedChartTip=null;describedChartTarget?.removeAttribute('aria-describedby');describedChartTarget=null;$('#chart-tooltip').hidden=true;}
function showChartTip(target,event){
  const data=target.dataset,tip=$('#chart-tooltip');
  tip.innerHTML=`<strong>${escapeHtml(data.tipLabel)}</strong><div><b>${escapeHtml(data.tipAmount)}</b><span>${escapeHtml(data.tipShare)}</span></div><small>of ${escapeHtml(data.tipDenominator)}</small>`;
  tip.hidden=false;
  const rect=target.getBoundingClientRect(),x=event?.clientX||rect.left+rect.width/2,y=event?.clientY||rect.top+rect.height/2;
  const width=tip.offsetWidth,height=tip.offsetHeight;
  tip.style.left=Math.max(8,Math.min(x+14,window.innerWidth-width-8))+'px';
  tip.style.top=Math.max(8,Math.min(y+14,window.innerHeight-height-8))+'px';
  if(describedChartTarget&&describedChartTarget!==target)describedChartTarget.removeAttribute('aria-describedby');
  target.setAttribute('aria-describedby','chart-tooltip');describedChartTarget=target;
}
function toggleChartTip(target,event){if(pinnedChartTip===target){hideChartTip(true);return;}pinnedChartTip=target;showChartTip(target,event);}
document.addEventListener('pointerover',e=>{const target=e.target.closest('[data-chart-tip]');if(target&&!pinnedChartTip)showChartTip(target,e);});
document.addEventListener('pointerout',e=>{const target=e.target.closest('[data-chart-tip]');if(target&&!target.contains(e.relatedTarget))hideChartTip();});
document.addEventListener('focusin',e=>{const target=e.target.closest('[data-chart-tip]');if(target&&!pinnedChartTip)showChartTip(target);});
document.addEventListener('focusout',e=>{if(e.target.closest('[data-chart-tip]'))hideChartTip();});
document.addEventListener('click',e=>{const target=e.target.closest('[data-chart-tip]');if(target)toggleChartTip(target,e);else hideChartTip(true);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideChartTip(true);return;}const target=e.target.closest('path[data-chart-tip]');if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();toggleChartTip(target);}});
window.addEventListener('scroll',()=>hideChartTip(true),true);
window.addEventListener('resize',()=>hideChartTip(true));

getCategories();normalizeCurrencies(state);
window.addEventListener('hashchange',navigate);navigate();
